CREATE TEMP TABLE curriculum_revised (payload jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO curriculum_revised(payload) VALUES ($guide_payload$[{"slug":"talora-human-resources-2026","task_number":1,"title":"Role Analysis","old_instructions":"[[AZ]]\n## Məqsəd\nNümunə junior rol seç ;  Əsas iş nəticələrini sadala ;  Vəzifəyə aid və aid olmayan tələbləri ayır.\n\n## Addım-addım icra\n1. Nümunə junior rol seç.\n2. Əsas iş nəticələrini sadala.\n3. Vəzifəyə aid və aid olmayan tələbləri ayır.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nRole analysis worksheet. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nChoose a sample junior role ;  Define expected work outcomes ;  Separate job-relevant from irrelevant requirements.\n\n## Step-by-step\n1. Choose a sample junior role.\n2. Define expected work outcomes.\n3. Separate job-relevant from irrelevant requirements.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nRole analysis worksheet. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nNümunə junior rol seç ;  Əsas iş nəticələrini sadala ;  Vəzifəyə aid və aid olmayan tələbləri ayır.\n\n[[EN]]\nChoose a sample junior role ;  Define expected work outcomes ;  Separate job-relevant from irrelevant requirements.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Role Analysis\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Yalnız uydurma namizəd və əməkdaş məlumatları ilə işləmək olar.\n**Nümunə situasiya:** Junior IT Support rolu üçün 5 iş nəticəsi yaz, yaş/cins kimi alakasız kriteriya qoyma.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Human Resources / Task-1. Yalnız uydurma namizəd və əməkdaşlardan ibarət nümunə qur; şəxsi məlumat və real CV toplama.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Nümunə junior rol seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Əsas iş nəticələrini sadala. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Vəzifəyə aid və aid olmayan tələbləri ayır. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Junior IT Support rolu üçün 5 iş nəticəsi yaz, yaş/cins kimi alakasız kriteriya qoyma. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Role analysis worksheet. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nJunior IT Support rolu üçün 5 iş nəticəsi yaz, yaş/cins kimi alakasız kriteriya qoyma.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Role analysis worksheet.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Qərəzli meyar, yaş, cins və şəxsi məlumatlardan istifadə etmə.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Role Analysis\nThis practical assignment is designed for beginners. Use fictional candidates and employee data only.\n**Example scenario:** Define five outcomes for a junior IT support role without unrelated age or gender requirements.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Human Resources / Task-1. Use fictional candidates and employees only; never collect real CVs or personal data.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Choose a sample junior role. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Define expected work outcomes. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Separate job-relevant from irrelevant requirements. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Define five outcomes for a junior IT support role without unrelated age or gender requirements. Document what worked and any limitations.\n7. Complete the main artifact: Role analysis worksheet. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nDefine five outcomes for a junior IT support role without unrelated age or gender requirements.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Role analysis worksheet.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Avoid biased criteria and sensitive personal information.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nRole Analysis: Nümunə junior rol seç. Əsas iş nəticələrini sadala. Vəzifəyə aid və aid olmayan tələbləri ayır. Pulsuz alətlər: Google Docs. Nəticə: Role analysis worksheet.\n\n[[EN]]\nRole Analysis: Choose a sample junior role. Define expected work outcomes. Separate job-relevant from irrelevant requirements. Free tools: Google Docs. Output: Role analysis worksheet."},{"slug":"talora-human-resources-2026","task_number":2,"title":"Competency Matrix","old_instructions":"[[AZ]]\n## Məqsəd\nBeş əsas bacarıq müəyyən et ;  Dörd pilləli səviyyə şkalası qur ;  Davranış əsaslı nümunələr yaz.\n\n## Addım-addım icra\n1. Beş əsas bacarıq müəyyən et.\n2. Dörd pilləli səviyyə şkalası qur.\n3. Davranış əsaslı nümunələr yaz.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nCompetency matrix. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nIdentify five core skills ;  Define four proficiency levels ;  Add observable behavior examples.\n\n## Step-by-step\n1. Identify five core skills.\n2. Define four proficiency levels.\n3. Add observable behavior examples.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nCompetency matrix. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nBeş əsas bacarıq müəyyən et ;  Dörd pilləli səviyyə şkalası qur ;  Davranış əsaslı nümunələr yaz.\n\n[[EN]]\nIdentify five core skills ;  Define four proficiency levels ;  Add observable behavior examples.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Competency Matrix\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Yalnız uydurma namizəd və əməkdaş məlumatları ilə işləmək olar.\n**Nümunə situasiya:** Ünsiyyət, Excel və problem həlli bacarıqlarını 1–4 səviyyə üzrə təsvir et.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Human Resources / Task-2. Yalnız uydurma namizəd və əməkdaşlardan ibarət nümunə qur; şəxsi məlumat və real CV toplama.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Beş əsas bacarıq müəyyən et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Dörd pilləli səviyyə şkalası qur. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Davranış əsaslı nümunələr yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Ünsiyyət, Excel və problem həlli bacarıqlarını 1–4 səviyyə üzrə təsvir et. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Competency matrix. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nÜnsiyyət, Excel və problem həlli bacarıqlarını 1–4 səviyyə üzrə təsvir et.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Competency matrix.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Qərəzli meyar, yaş, cins və şəxsi məlumatlardan istifadə etmə.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Competency Matrix\nThis practical assignment is designed for beginners. Use fictional candidates and employee data only.\n**Example scenario:** Describe communication, spreadsheets and troubleshooting on a four-level competency rubric.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Human Resources / Task-2. Use fictional candidates and employees only; never collect real CVs or personal data.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Identify five core skills. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Define four proficiency levels. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Add observable behavior examples. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Describe communication, spreadsheets and troubleshooting on a four-level competency rubric. Document what worked and any limitations.\n7. Complete the main artifact: Competency matrix. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nDescribe communication, spreadsheets and troubleshooting on a four-level competency rubric.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Competency matrix.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Avoid biased criteria and sensitive personal information.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nCompetency Matrix: Beş əsas bacarıq müəyyən et. Dörd pilləli səviyyə şkalası qur. Davranış əsaslı nümunələr yaz. Pulsuz alətlər: Google Sheets. Nəticə: Competency matrix.\n\n[[EN]]\nCompetency Matrix: Identify five core skills. Define four proficiency levels. Add observable behavior examples. Free tools: Google Sheets. Output: Competency matrix."},{"slug":"talora-human-resources-2026","task_number":3,"title":"Inclusive Job Description","old_instructions":"[[AZ]]\n## Məqsəd\nAydın və inklüziv vakansiya mətni yaz ;  Obyektiv tələbləri ayır ;  Diskriminasiya yarada bilən ifadələri təmizlə.\n\n## Addım-addım icra\n1. Aydın və inklüziv vakansiya mətni yaz.\n2. Obyektiv tələbləri ayır.\n3. Diskriminasiya yarada bilən ifadələri təmizlə.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nJob description draft. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nDraft an inclusive job post ;  Separate objective requirements ;  Remove discriminatory wording.\n\n## Step-by-step\n1. Draft an inclusive job post.\n2. Separate objective requirements.\n3. Remove discriminatory wording.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nJob description draft. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nAydın və inklüziv vakansiya mətni yaz ;  Obyektiv tələbləri ayır ;  Diskriminasiya yarada bilən ifadələri təmizlə.\n\n[[EN]]\nDraft an inclusive job post ;  Separate objective requirements ;  Remove discriminatory wording.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Inclusive Job Description\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Yalnız uydurma namizəd və əməkdaş məlumatları ilə işləmək olar.\n**Nümunə situasiya:** 'Enerjili gənc' kimi ifadəni ölçülə bilən bacarıqla əvəz edən vakansiya mətni yaz.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Human Resources / Task-3. Yalnız uydurma namizəd və əməkdaşlardan ibarət nümunə qur; şəxsi məlumat və real CV toplama.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Aydın və inklüziv vakansiya mətni yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Obyektiv tələbləri ayır. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Diskriminasiya yarada bilən ifadələri təmizlə. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 'Enerjili gənc' kimi ifadəni ölçülə bilən bacarıqla əvəz edən vakansiya mətni yaz. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Job description draft. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n'Enerjili gənc' kimi ifadəni ölçülə bilən bacarıqla əvəz edən vakansiya mətni yaz.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Job description draft.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Qərəzli meyar, yaş, cins və şəxsi məlumatlardan istifadə etmə.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Inclusive Job Description\nThis practical assignment is designed for beginners. Use fictional candidates and employee data only.\n**Example scenario:** Replace stereotyped job-ad language with measurable skills and outcomes.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Human Resources / Task-3. Use fictional candidates and employees only; never collect real CVs or personal data.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Draft an inclusive job post. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Separate objective requirements. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Remove discriminatory wording. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Replace stereotyped job-ad language with measurable skills and outcomes. Document what worked and any limitations.\n7. Complete the main artifact: Job description draft. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nReplace stereotyped job-ad language with measurable skills and outcomes.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Job description draft.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Avoid biased criteria and sensitive personal information.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nInclusive Job Description: Aydın və inklüziv vakansiya mətni yaz. Obyektiv tələbləri ayır. Diskriminasiya yarada bilən ifadələri təmizlə. Pulsuz alətlər: Google Docs. Nəticə: Job description draft.\n\n[[EN]]\nInclusive Job Description: Draft an inclusive job post. Separate objective requirements. Remove discriminatory wording. Free tools: Google Docs. Output: Job description draft."},{"slug":"talora-human-resources-2026","task_number":4,"title":"Candidate Evaluation Rubric","old_instructions":"[[AZ]]\n## Məqsəd\nQiymətləndirmə meyarlarını rol ilə bağla ;  Şəffaf bal sistemi hazırla ;  İki sintetik namizədi müqayisə et.\n\n## Addım-addım icra\n1. Qiymətləndirmə meyarlarını rol ilə bağla.\n2. Şəffaf bal sistemi hazırla.\n3. İki sintetik namizədi müqayisə et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nSelection rubric. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nLink scoring criteria to role needs ;  Create a clear scorecard ;  Compare two fictional candidates.\n\n## Step-by-step\n1. Link scoring criteria to role needs.\n2. Create a clear scorecard.\n3. Compare two fictional candidates.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nSelection rubric. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nQiymətləndirmə meyarlarını rol ilə bağla ;  Şəffaf bal sistemi hazırla ;  İki sintetik namizədi müqayisə et.\n\n[[EN]]\nLink scoring criteria to role needs ;  Create a clear scorecard ;  Compare two fictional candidates.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Candidate Evaluation Rubric\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Yalnız uydurma namizəd və əməkdaş məlumatları ilə işləmək olar.\n**Nümunə situasiya:** A və B adlı iki uydurma namizədi eyni 5 kriteriya üzrə qiymətləndir.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Human Resources / Task-4. Yalnız uydurma namizəd və əməkdaşlardan ibarət nümunə qur; şəxsi məlumat və real CV toplama.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Qiymətləndirmə meyarlarını rol ilə bağla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Şəffaf bal sistemi hazırla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. İki sintetik namizədi müqayisə et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: A və B adlı iki uydurma namizədi eyni 5 kriteriya üzrə qiymətləndir. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Selection rubric. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nA və B adlı iki uydurma namizədi eyni 5 kriteriya üzrə qiymətləndir.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Selection rubric.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Qərəzli meyar, yaş, cins və şəxsi məlumatlardan istifadə etmə.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Candidate Evaluation Rubric\nThis practical assignment is designed for beginners. Use fictional candidates and employee data only.\n**Example scenario:** Score two fictional candidates A and B against the same five criteria.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Human Resources / Task-4. Use fictional candidates and employees only; never collect real CVs or personal data.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Link scoring criteria to role needs. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Create a clear scorecard. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Compare two fictional candidates. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Score two fictional candidates A and B against the same five criteria. Document what worked and any limitations.\n7. Complete the main artifact: Selection rubric. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nScore two fictional candidates A and B against the same five criteria.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Selection rubric.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Avoid biased criteria and sensitive personal information.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nCandidate Evaluation Rubric: Qiymətləndirmə meyarlarını rol ilə bağla. Şəffaf bal sistemi hazırla. İki sintetik namizədi müqayisə et. Pulsuz alətlər: Google Sheets. Nəticə: Selection rubric.\n\n[[EN]]\nCandidate Evaluation Rubric: Link scoring criteria to role needs. Create a clear scorecard. Compare two fictional candidates. Free tools: Google Sheets. Output: Selection rubric."},{"slug":"talora-human-resources-2026","task_number":5,"title":"Structured Interview","old_instructions":"[[AZ]]\n## Məqsəd\nAltı situasiya sualı yaz ;  Hər suala scoring guide əlavə et ;  İki müsahibəçi arasında kalibrasiyanı izah et.\n\n## Addım-addım icra\n1. Altı situasiya sualı yaz.\n2. Hər suala scoring guide əlavə et.\n3. İki müsahibəçi arasında kalibrasiyanı izah et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nStructured interview kit. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nWrite six situational questions ;  Add a scoring guide ;  Explain interviewer calibration.\n\n## Step-by-step\n1. Write six situational questions.\n2. Add a scoring guide.\n3. Explain interviewer calibration.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nStructured interview kit. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nAltı situasiya sualı yaz ;  Hər suala scoring guide əlavə et ;  İki müsahibəçi arasında kalibrasiyanı izah et.\n\n[[EN]]\nWrite six situational questions ;  Add a scoring guide ;  Explain interviewer calibration.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Structured Interview\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Yalnız uydurma namizəd və əməkdaş məlumatları ilə işləmək olar.\n**Nümunə situasiya:** Müştəri şikayəti ssenarisinə 6 sual və 0–3 bal rubriki hazırla.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Human Resources / Task-5. Yalnız uydurma namizəd və əməkdaşlardan ibarət nümunə qur; şəxsi məlumat və real CV toplama.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Altı situasiya sualı yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Hər suala scoring guide əlavə et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. İki müsahibəçi arasında kalibrasiyanı izah et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Müştəri şikayəti ssenarisinə 6 sual və 0–3 bal rubriki hazırla. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Structured interview kit. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nMüştəri şikayəti ssenarisinə 6 sual və 0–3 bal rubriki hazırla.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Structured interview kit.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Qərəzli meyar, yaş, cins və şəxsi məlumatlardan istifadə etmə.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Structured Interview\nThis practical assignment is designed for beginners. Use fictional candidates and employee data only.\n**Example scenario:** Create six structured customer-complaint interview questions and a 0–3 rubric.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Human Resources / Task-5. Use fictional candidates and employees only; never collect real CVs or personal data.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Write six situational questions. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Add a scoring guide. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Explain interviewer calibration. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Create six structured customer-complaint interview questions and a 0–3 rubric. Document what worked and any limitations.\n7. Complete the main artifact: Structured interview kit. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCreate six structured customer-complaint interview questions and a 0–3 rubric.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Structured interview kit.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Avoid biased criteria and sensitive personal information.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nStructured Interview: Altı situasiya sualı yaz. Hər suala scoring guide əlavə et. İki müsahibəçi arasında kalibrasiyanı izah et. Pulsuz alətlər: Google Docs. Nəticə: Structured interview kit.\n\n[[EN]]\nStructured Interview: Write six situational questions. Add a scoring guide. Explain interviewer calibration. Free tools: Google Docs. Output: Structured interview kit."},{"slug":"talora-human-resources-2026","task_number":6,"title":"Onboarding Journey","old_instructions":"[[AZ]]\n## Məqsəd\nİlk 30 gün üçün plan hazırla ;  Təlim və resurs ehtiyaclarını cədvəlləşdir ;  7 və 30-cu gün check-in forması yarat.\n\n## Addım-addım icra\n1. İlk 30 gün üçün plan hazırla.\n2. Təlim və resurs ehtiyaclarını cədvəlləşdir.\n3. 7 və 30-cu gün check-in forması yarat.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\n30-day onboarding plan. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nPlan the first 30 days ;  Map training and resources ;  Draft day-seven and day-thirty check-ins.\n\n## Step-by-step\n1. Plan the first 30 days.\n2. Map training and resources.\n3. Draft day-seven and day-thirty check-ins.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\n30-day onboarding plan. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nİlk 30 gün üçün plan hazırla ;  Təlim və resurs ehtiyaclarını cədvəlləşdir ;  7 və 30-cu gün check-in forması yarat.\n\n[[EN]]\nPlan the first 30 days ;  Map training and resources ;  Draft day-seven and day-thirty check-ins.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Onboarding Journey\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Yalnız uydurma namizəd və əməkdaş məlumatları ilə işləmək olar.\n**Nümunə situasiya:** İlk 1, 7 və 30 gün üçün giriş, təlim və nəticə checkpoint-ləri qur.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Human Resources / Task-6. Yalnız uydurma namizəd və əməkdaşlardan ibarət nümunə qur; şəxsi məlumat və real CV toplama.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. İlk 30 gün üçün plan hazırla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Təlim və resurs ehtiyaclarını cədvəlləşdir. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. 7 və 30-cu gün check-in forması yarat. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: İlk 1, 7 və 30 gün üçün giriş, təlim və nəticə checkpoint-ləri qur. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: 30-day onboarding plan. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nİlk 1, 7 və 30 gün üçün giriş, təlim və nəticə checkpoint-ləri qur.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** 30-day onboarding plan.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Qərəzli meyar, yaş, cins və şəxsi məlumatlardan istifadə etmə.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Onboarding Journey\nThis practical assignment is designed for beginners. Use fictional candidates and employee data only.\n**Example scenario:** Plan onboarding checkpoints for days 1, 7 and 30 with clear deliverables.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Human Resources / Task-6. Use fictional candidates and employees only; never collect real CVs or personal data.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Plan the first 30 days. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Map training and resources. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Draft day-seven and day-thirty check-ins. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Plan onboarding checkpoints for days 1, 7 and 30 with clear deliverables. Document what worked and any limitations.\n7. Complete the main artifact: 30-day onboarding plan. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nPlan onboarding checkpoints for days 1, 7 and 30 with clear deliverables.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** 30-day onboarding plan.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Avoid biased criteria and sensitive personal information.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nOnboarding Journey: İlk 30 gün üçün plan hazırla. Təlim və resurs ehtiyaclarını cədvəlləşdir. 7 və 30-cu gün check-in forması yarat. Pulsuz alətlər: Google Sheets. Nəticə: 30-day onboarding plan.\n\n[[EN]]\nOnboarding Journey: Plan the first 30 days. Map training and resources. Draft day-seven and day-thirty check-ins. Free tools: Google Sheets. Output: 30-day onboarding plan."},{"slug":"talora-human-resources-2026","task_number":7,"title":"Learning Needs Assessment","old_instructions":"[[AZ]]\n## Məqsəd\nSintetik komanda ssenarisi qur ;  Skill gap təhlili et ;  Üç təlim müdaxiləsini prioritetləşdir.\n\n## Addım-addım icra\n1. Sintetik komanda ssenarisi qur.\n2. Skill gap təhlili et.\n3. Üç təlim müdaxiləsini prioritetləşdir.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nL&D needs analysis. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nUse a fictional team scenario ;  Analyze skill gaps ;  Prioritize three learning interventions.\n\n## Step-by-step\n1. Use a fictional team scenario.\n2. Analyze skill gaps.\n3. Prioritize three learning interventions.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nL&D needs analysis. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nSintetik komanda ssenarisi qur ;  Skill gap təhlili et ;  Üç təlim müdaxiləsini prioritetləşdir.\n\n[[EN]]\nUse a fictional team scenario ;  Analyze skill gaps ;  Prioritize three learning interventions.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Learning Needs Assessment\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Yalnız uydurma namizəd və əməkdaş məlumatları ilə işləmək olar.\n**Nümunə situasiya:** 6 uydurma komanda üzvünün Excel boşluqlarından təlim ehtiyacı çıxart.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Human Resources / Task-7. Yalnız uydurma namizəd və əməkdaşlardan ibarət nümunə qur; şəxsi məlumat və real CV toplama.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Sintetik komanda ssenarisi qur. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Skill gap təhlili et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Üç təlim müdaxiləsini prioritetləşdir. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 6 uydurma komanda üzvünün Excel boşluqlarından təlim ehtiyacı çıxart. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: L&D needs analysis. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n6 uydurma komanda üzvünün Excel boşluqlarından təlim ehtiyacı çıxart.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** L&D needs analysis.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Qərəzli meyar, yaş, cins və şəxsi məlumatlardan istifadə etmə.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Learning Needs Assessment\nThis practical assignment is designed for beginners. Use fictional candidates and employee data only.\n**Example scenario:** Identify training needs from fictional spreadsheet skills for six team members.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Human Resources / Task-7. Use fictional candidates and employees only; never collect real CVs or personal data.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Use a fictional team scenario. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Analyze skill gaps. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Prioritize three learning interventions. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Identify training needs from fictional spreadsheet skills for six team members. Document what worked and any limitations.\n7. Complete the main artifact: L&D needs analysis. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nIdentify training needs from fictional spreadsheet skills for six team members.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** L&D needs analysis.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Avoid biased criteria and sensitive personal information.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nLearning Needs Assessment: Sintetik komanda ssenarisi qur. Skill gap təhlili et. Üç təlim müdaxiləsini prioritetləşdir. Pulsuz alətlər: Google Sheets. Nəticə: L&D needs analysis.\n\n[[EN]]\nLearning Needs Assessment: Use a fictional team scenario. Analyze skill gaps. Prioritize three learning interventions. Free tools: Google Sheets. Output: L&D needs analysis."},{"slug":"talora-human-resources-2026","task_number":8,"title":"Anonymous Feedback Survey","old_instructions":"[[AZ]]\n## Məqsəd\nİnklüziv qısa sorğu hazırla ;  Fərdi identifikasiya riskini araşdır ;  Sintetik nəticələri qrafiklə ümumiləşdir.\n\n## Addım-addım icra\n1. İnklüziv qısa sorğu hazırla.\n2. Fərdi identifikasiya riskini araşdır.\n3. Sintetik nəticələri qrafiklə ümumiləşdir.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nSurvey and privacy note. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nDesign a short inclusive survey ;  Assess identification risks ;  Summarize synthetic findings in a chart.\n\n## Step-by-step\n1. Design a short inclusive survey.\n2. Assess identification risks.\n3. Summarize synthetic findings in a chart.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nSurvey and privacy note. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nİnklüziv qısa sorğu hazırla ;  Fərdi identifikasiya riskini araşdır ;  Sintetik nəticələri qrafiklə ümumiləşdir.\n\n[[EN]]\nDesign a short inclusive survey ;  Assess identification risks ;  Summarize synthetic findings in a chart.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Anonymous Feedback Survey\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Yalnız uydurma namizəd və əməkdaş məlumatları ilə işləmək olar.\n**Nümunə situasiya:** İş mühiti haqqında 6 anonim sorğu sualı və sintetik cavab xülasəsi yaz.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Forms** — https://forms.google.com. Blank form aç, sualları əlavə et, yalnız uydurma cavablarla sına.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Human Resources / Task-8. Yalnız uydurma namizəd və əməkdaşlardan ibarət nümunə qur; şəxsi məlumat və real CV toplama.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. İnklüziv qısa sorğu hazırla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Fərdi identifikasiya riskini araşdır. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Sintetik nəticələri qrafiklə ümumiləşdir. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: İş mühiti haqqında 6 anonim sorğu sualı və sintetik cavab xülasəsi yaz. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Survey and privacy note. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nİş mühiti haqqında 6 anonim sorğu sualı və sintetik cavab xülasəsi yaz.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Survey and privacy note.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Qərəzli meyar, yaş, cins və şəxsi məlumatlardan istifadə etmə.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Anonymous Feedback Survey\nThis practical assignment is designed for beginners. Use fictional candidates and employee data only.\n**Example scenario:** Create six anonymous workplace survey items and a synthetic results summary.\n\n## Free tools and platforms\n- **Google Forms** — https://forms.google.com. Build a blank form, add questions and test with fictional responses.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Human Resources / Task-8. Use fictional candidates and employees only; never collect real CVs or personal data.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Design a short inclusive survey. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Assess identification risks. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Summarize synthetic findings in a chart. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Create six anonymous workplace survey items and a synthetic results summary. Document what worked and any limitations.\n7. Complete the main artifact: Survey and privacy note. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCreate six anonymous workplace survey items and a synthetic results summary.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Survey and privacy note.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Avoid biased criteria and sensitive personal information.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nAnonymous Feedback Survey: İnklüziv qısa sorğu hazırla. Fərdi identifikasiya riskini araşdır. Sintetik nəticələri qrafiklə ümumiləşdir. Pulsuz alətlər: Google Forms. Nəticə: Survey and privacy note.\n\n[[EN]]\nAnonymous Feedback Survey: Design a short inclusive survey. Assess identification risks. Summarize synthetic findings in a chart. Free tools: Google Forms. Output: Survey and privacy note."},{"slug":"talora-human-resources-2026","task_number":9,"title":"Fairness and Data Retention","old_instructions":"[[AZ]]\n## Məqsəd\nNamizəd məlumatlarının həyat dövrünü çək ;  Minimal toplama prinsipi tətbiq et ;  Silinmə və giriş qaydalarını yaz.\n\n## Addım-addım icra\n1. Namizəd məlumatlarının həyat dövrünü çək.\n2. Minimal toplama prinsipi tətbiq et.\n3. Silinmə və giriş qaydalarını yaz.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nHR privacy checklist. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nDiagram candidate data lifecycle ;  Apply data minimization ;  Document deletion and access controls.\n\n## Step-by-step\n1. Diagram candidate data lifecycle.\n2. Apply data minimization.\n3. Document deletion and access controls.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nHR privacy checklist. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nNamizəd məlumatlarının həyat dövrünü çək ;  Minimal toplama prinsipi tətbiq et ;  Silinmə və giriş qaydalarını yaz.\n\n[[EN]]\nDiagram candidate data lifecycle ;  Apply data minimization ;  Document deletion and access controls.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Fairness and Data Retention\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Yalnız uydurma namizəd və əməkdaş məlumatları ilə işləmək olar.\n**Nümunə situasiya:** Namizəd məlumatının toplanma, istifadə, məhdud giriş və silinmə sxemini çək.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Human Resources / Task-9. Yalnız uydurma namizəd və əməkdaşlardan ibarət nümunə qur; şəxsi məlumat və real CV toplama.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Namizəd məlumatlarının həyat dövrünü çək. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Minimal toplama prinsipi tətbiq et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Silinmə və giriş qaydalarını yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Namizəd məlumatının toplanma, istifadə, məhdud giriş və silinmə sxemini çək. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: HR privacy checklist. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nNamizəd məlumatının toplanma, istifadə, məhdud giriş və silinmə sxemini çək.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** HR privacy checklist.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Qərəzli meyar, yaş, cins və şəxsi məlumatlardan istifadə etmə.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Fairness and Data Retention\nThis practical assignment is designed for beginners. Use fictional candidates and employee data only.\n**Example scenario:** Map collection, restricted access, usage and deletion of applicant information.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Human Resources / Task-9. Use fictional candidates and employees only; never collect real CVs or personal data.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Diagram candidate data lifecycle. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Apply data minimization. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Document deletion and access controls. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Map collection, restricted access, usage and deletion of applicant information. Document what worked and any limitations.\n7. Complete the main artifact: HR privacy checklist. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nMap collection, restricted access, usage and deletion of applicant information.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** HR privacy checklist.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Avoid biased criteria and sensitive personal information.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nFairness and Data Retention: Namizəd məlumatlarının həyat dövrünü çək. Minimal toplama prinsipi tətbiq et. Silinmə və giriş qaydalarını yaz. Pulsuz alətlər: Google Docs. Nəticə: HR privacy checklist.\n\n[[EN]]\nFairness and Data Retention: Diagram candidate data lifecycle. Apply data minimization. Document deletion and access controls. Free tools: Google Docs. Output: HR privacy checklist."},{"slug":"talora-human-resources-2026","task_number":10,"title":"HR Process Portfolio","old_instructions":"[[AZ]]\n## Məqsəd\nBütün formaları birləşdir ;  İşə qəbul prosesini end-to-end təsvir et ;  Etik risklər və təkmilləşdirmələri təqdim et.\n\n## Addım-addım icra\n1. Bütün formaları birləşdir.\n2. İşə qəbul prosesini end-to-end təsvir et.\n3. Etik risklər və təkmilləşdirmələri təqdim et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nHR workflow portfolio. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nCombine the templates ;  Describe the end-to-end hiring journey ;  Present ethical risks and improvements.\n\n## Step-by-step\n1. Combine the templates.\n2. Describe the end-to-end hiring journey.\n3. Present ethical risks and improvements.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nHR workflow portfolio. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nBütün formaları birləşdir ;  İşə qəbul prosesini end-to-end təsvir et ;  Etik risklər və təkmilləşdirmələri təqdim et.\n\n[[EN]]\nCombine the templates ;  Describe the end-to-end hiring journey ;  Present ethical risks and improvements.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: HR Process Portfolio\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Yalnız uydurma namizəd və əməkdaş məlumatları ilə işləmək olar.\n**Nümunə situasiya:** Vakansiya → qiymətləndirmə → müsahibə → onboarding sənədlərini portfelə yığ.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Slides** — https://slides.google.com. Bir slaydda bir əsas fikir yerləşdir, sonunda PDF eksport et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Human Resources / Task-10. Yalnız uydurma namizəd və əməkdaşlardan ibarət nümunə qur; şəxsi məlumat və real CV toplama.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Bütün formaları birləşdir. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. İşə qəbul prosesini end-to-end təsvir et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Etik risklər və təkmilləşdirmələri təqdim et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Vakansiya → qiymətləndirmə → müsahibə → onboarding sənədlərini portfelə yığ. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: HR workflow portfolio. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nVakansiya → qiymətləndirmə → müsahibə → onboarding sənədlərini portfelə yığ.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** HR workflow portfolio.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Qərəzli meyar, yaş, cins və şəxsi məlumatlardan istifadə etmə.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: HR Process Portfolio\nThis practical assignment is designed for beginners. Use fictional candidates and employee data only.\n**Example scenario:** Combine job post, assessment, interview and onboarding assets in one HR portfolio.\n\n## Free tools and platforms\n- **Google Slides** — https://slides.google.com. Use one idea per slide, then export the presentation as PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Human Resources / Task-10. Use fictional candidates and employees only; never collect real CVs or personal data.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Combine the templates. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Describe the end-to-end hiring journey. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Present ethical risks and improvements. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Combine job post, assessment, interview and onboarding assets in one HR portfolio. Document what worked and any limitations.\n7. Complete the main artifact: HR workflow portfolio. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCombine job post, assessment, interview and onboarding assets in one HR portfolio.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** HR workflow portfolio.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Avoid biased criteria and sensitive personal information.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nHR Process Portfolio: Bütün formaları birləşdir. İşə qəbul prosesini end-to-end təsvir et. Etik risklər və təkmilləşdirmələri təqdim et. Pulsuz alətlər: Google Slides. Nəticə: HR workflow portfolio.\n\n[[EN]]\nHR Process Portfolio: Combine the templates. Describe the end-to-end hiring journey. Present ethical risks and improvements. Free tools: Google Slides. Output: HR workflow portfolio."}]$guide_payload$::jsonb);
DO $preflight$
DECLARE matched integer;
BEGIN
 SELECT COUNT(*) INTO matched FROM curriculum_revised c
 CROSS JOIN LATERAL jsonb_array_elements(c.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id
   AND t.task_number=(e.item->>'task_number')::integer
   AND t.title=e.item->>'title'
 WHERE t.instructions=e.item->>'old_instructions'
 AND t.description=e.item->>'old_description'
 AND i.slug='talora-human-resources-2026';
 IF (SELECT jsonb_array_length(payload) FROM curriculum_revised)<>10 OR matched<>10 THEN
  RAISE EXCEPTION 'Content version mismatch for talora-human-resources-2026; matched %',matched;
 END IF;
END; $preflight$;
UPDATE public.internship_tasks t
SET instructions=e.item->>'new_instructions', description=e.item->>'new_description'
FROM curriculum_revised c
CROSS JOIN LATERAL jsonb_array_elements(c.payload) e(item)
JOIN public.internships i ON i.slug=e.item->>'slug'
WHERE i.slug='talora-human-resources-2026'
AND t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
AND t.title=e.item->>'title';
DO $verify$
DECLARE matched integer;
BEGIN
 SELECT COUNT(*) INTO matched FROM curriculum_revised c
 CROSS JOIN LATERAL jsonb_array_elements(c.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE t.instructions=e.item->>'new_instructions' AND t.description=e.item->>'new_description'
 AND t.status='published' AND t.is_required AND i.slug='talora-human-resources-2026';
 IF matched<>10 THEN RAISE EXCEPTION 'Verification failed after update for talora-human-resources-2026: %',matched; END IF;
END; $verify$;
COMMIT;